def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_prime_factors(n):
    factors = []
    for i in range(2, n + 1):
        while n % i == 0 and is_prime(i):
            factors.append(i)
            n //= i
    return sum(factors)

def create_sorted_dict(num_dict):
    result_dict = {key: sum_prime_factors(key) for key in num_dict}
    sorted_list = sorted(result_dict.items(), key=lambda x: x[1])
    return result_dict, sorted_list

